"use client"

import * as React from "react"
import { EllipsisVertical } from "lucide-react"
import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage, type AvatarColor } from "@/components/ui/avatar"
import { IconButton } from "@/components/ui/icon-button"

/* ------------------------------------------------------------------ */
/* Shared: tiny initials avatar stack used by kanban/agenda/task rows  */
/* ------------------------------------------------------------------ */

type Person = { name: string; initials?: string; src?: string; color?: AvatarColor }

const initialsOf = (p: Person) => p.initials ?? p.name.split(" ").map((s) => s[0]).slice(0, 2).join("").toUpperCase()

function AvatarStack({ people, size = "sm", max = 3, className }: { people: Person[]; size?: "sm" | "xs" | "default"; max?: number; className?: string }) {
  const shown = people.slice(0, max)
  const rest = people.length - shown.length
  return (
    <div data-slot="avatar-stack" className={cn("flex items-center -space-x-1", className)}>
      {shown.map((p, i) => (
        <Avatar key={`${p.name}-${i}`} size={size} color={p.src ? undefined : (p.color ?? "indigo")} className="ring-2 ring-card" title={p.name}>
          {p.src && <AvatarImage src={p.src} alt={p.name} />}
          <AvatarFallback className="text-[10px]">{initialsOf(p)}</AvatarFallback>
        </Avatar>
      ))}
      {rest > 0 && (
        // An Avatar of the same size, so the count is as big as the faces next to it.
        <Avatar size={size} className="ring-2 ring-card">
          <AvatarFallback className="text-[10px] font-medium text-text-secondary">+{rest}</AvatarFallback>
        </Avatar>
      )}
    </div>
  )
}

/* ------------------------------------------------------------------ */
/* Event Chip + Agenda Event (calendar)                                */
/* Figma: Event Chip (722:112), Agenda Event (722:129)                 */
/* ------------------------------------------------------------------ */

type EventColor = "indigo" | "blue" | "purple" | "pink" | "red" | "orange" | "yellow" | "green"

const EVENT_BAR: Record<EventColor, string> = {
  indigo: "bg-primary",
  blue: "bg-brand-secondary",
  purple: "bg-chart-3",
  pink: "bg-brand-tertiary",
  red: "bg-destructive",
  orange: "bg-brand-septenary",
  yellow: "bg-brand-quaternary",
  green: "bg-success",
}

type AgendaEventProps = {
  start: React.ReactNode
  end?: React.ReactNode
  title: React.ReactNode
  meta?: React.ReactNode
  color?: EventColor
  guests?: Person[]
  onMenu?: () => void
  onClick?: () => void
  className?: string
}

function AgendaEvent({ start, end, title, meta, color = "purple", guests, onMenu, onClick, className }: AgendaEventProps) {
  return (
    // onClick: the title becomes a real button stretched over the row (keyboard and pointer),
    // the menu sits above it, so no interactive element is nested in another.
    <div
      data-slot="agenda-event"
      className={cn("relative flex flex-wrap items-center gap-x-3 gap-y-2 border-b border-border px-5 py-3", onClick && "cursor-pointer hover:bg-muted/50 has-[[data-stretch]:focus-visible]:focus-ring-on has-[[data-stretch]:focus-visible]:-outline-offset-2", className)}
    >
      <div className="flex w-16 shrink-0 flex-col">
        <span className="text-xs font-medium text-foreground">{start}</span>
        {end && <span className="text-[11px] text-text-tertiary">{end}</span>}
      </div>
      <span className={cn("h-8 w-[3px] shrink-0 rounded-full", EVENT_BAR[color])} />
      <div className="flex min-w-[7rem] flex-1 flex-col">
        {onClick ? (
          <button type="button" data-stretch onClick={onClick} className="line-clamp-2 break-words text-sm font-medium text-foreground text-left outline-none after:absolute after:inset-0 after:rounded-[inherit] after:content-['']">
            {title}
          </button>
        ) : (
          <span className="line-clamp-2 break-words text-sm font-medium text-foreground">{title}</span>
        )}
        {meta && <span className="truncate text-xs text-text-tertiary">{meta}</span>}
      </div>
      {/* the guests and the menu wrap below the title when the row is too narrow for all of it, so the title always keeps its room */}
      {((guests && guests.length > 0) || onMenu) && (
        <div className="ml-auto flex shrink-0 items-center gap-3">
          {guests && guests.length > 0 && <AvatarStack people={guests} size="sm" />}
          {onMenu && (
            <IconButton variant="ghost" size="sm" aria-label="Event menu" className="relative z-10" onClick={(e) => { e.stopPropagation(); onMenu() }}>
              <EllipsisVertical className="size-4" strokeWidth={1.5} />
            </IconButton>
          )}
        </div>
      )}
    </div>
  )
}

export { AvatarStack, AgendaEvent }
export type { Person, EventColor, AgendaEventProps }

import * as React from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { Check, Loader2, RotateCw } from "lucide-react"
import { cn } from "@/lib/utils"

// Same states as Button (see button.tsx and the Figma Button / Icon set): the filled variants use fixed
// hover and pressed fills (brand-700/800, red-800/900, dark-400/500, bg-page/bg-subtle on neutral surfaces)
// instead of brightness-95, and focus is the shared 2 px focus-ring (owner rule 31 Oct 2026). The gradient top
// stop is 85 % primary + 15 % brand-500 (4.73:1 with a white icon); hover and pressed step the gradient to
// brand-600/700 and brand-700/800. The light variant's icon is light-1000 (5.93:1 on light-600); it has no
// Figma counterpart, hover and pressed step to the lighter light-500 and light-400 so the icon keeps >= 3:1.
const iconButtonVariants = cva(
  "group/icon-button inline-flex shrink-0 items-center justify-center border border-transparent transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:scale-[0.97] motion-reduce:active:scale-100 disabled:pointer-events-none disabled:opacity-40 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-bg-page data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        primary:
          "border-primary bg-primary text-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        gradient:
          "border-primary bg-gradient-to-b from-[color-mix(in_srgb,var(--primary)_85%,var(--brand-500))] to-primary text-primary-foreground shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05),inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:from-(--brand-600) hover:to-(--brand-700) active:from-(--brand-700) active:to-(--brand-800) focus-ring",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-white active:bg-(--dark-500) active:text-white focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-0 focus-visible:outline-(color:--dark-300)",
        light: "bg-(--light-600) text-(--light-1000) hover:bg-(--light-500) data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-(--light-400) focus-ring",
        outline: "bg-card border-primary text-foreground hover:border-tint-text-indigo hover:bg-tint-indigo hover:text-tint-text-indigo data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        // Figma Type=ghost / destructive (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-bg-page data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:border-red-800 hover:bg-red-800 active:border-red-900 active:bg-red-900 focus-ring-error",
      },
      shape: {
        rounded: "rounded-md",
        circle: "rounded-full",
      },
      size: {
        sm: "size-8 [&_svg]:size-4",
        md: "size-9 [&_svg]:size-[18px]",
        lg: "size-10 [&_svg]:size-5",
        xl: "size-11 [&_svg]:size-[22px]",
        "2xl": "size-12 [&_svg]:size-6",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

type IconButtonPhase = "idle" | "pending" | "success" | "error"

function IconButton({
  className,
  variant,
  shape,
  size,
  children,
  onClick,
  pending,
  phase,
  expanded,
  ...props
}: ButtonPrimitive.Props &
  VariantProps<typeof iconButtonVariants> & {
    /**
     * Shows a spinner in place of the icon, in the same square, and ignores presses.
     * The button stays focusable and keeps its colour (it is not disabled).
     */
    pending?: boolean
    /**
     * Async feedback in the same square: pending shows a spinner, success a check, error a retry icon.
     * The size never changes. The accessible name is yours: change the aria-label with the phase
     * (for example Copy link, Copying, Copied, Retry copying).
     */
    phase?: IconButtonPhase
    /**
     * Marks a trigger whose menu or panel is open: sets aria-expanded and the pressed surface
     * (bg-bg-subtle) on the quiet variants. Leave it undefined when the button does not control a popup.
     */
    expanded?: boolean
  }) {
  const status: IconButtonPhase = phase ?? (pending ? "pending" : "idle")
  const isIdle = status === "idle"

  const resolvedVariant = variant ?? "primary"
  const effectiveVariant =
    status === "error" && ["primary", "brand", "gradient"].includes(resolvedVariant)
      ? "destructive"
      : variant

  const quiet = ["plain", "ghost", "outline"].includes(resolvedVariant)

  let statusIcon: React.ReactNode = null
  if (status === "pending") {
    statusIcon = (
      <Loader2 aria-hidden className="animate-spin motion-reduce:animate-none" />
    )
  } else if (status === "success") {
    statusIcon = (
      <Check aria-hidden strokeWidth={1.5} className={quiet ? "text-text-success" : undefined} />
    )
  } else if (status === "error") {
    statusIcon = (
      <RotateCw aria-hidden strokeWidth={1.5} className={quiet ? "text-text-error" : undefined} />
    )
  }

  const handleClick: NonNullable<ButtonPrimitive.Props["onClick"]> = (event) => {
    if (status === "pending") {
      event.preventDefault()
      return
    }
    onClick?.(event)
  }

  return (
    <ButtonPrimitive
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant: isIdle ? variant : effectiveVariant, shape, size, className }))}
      aria-expanded={expanded}
      data-expanded={expanded ? "" : undefined}
      data-phase={isIdle ? undefined : status}
      aria-busy={isIdle ? undefined : status === "pending" ? true : undefined}
      data-pending={isIdle ? undefined : status === "pending" ? "" : undefined}
      onClick={isIdle ? onClick : handleClick}
      {...props}
    >
      {isIdle ? children : statusIcon}
    </ButtonPrimitive>
  )
}

export { IconButton, iconButtonVariants }
export type { IconButtonPhase }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

"use client"

import * as React from "react"
import { Avatar as AvatarPrimitive } from "@base-ui/react/avatar"
import { Check, Moon } from "lucide-react"
import { cn } from "@/lib/utils"
import { opticalCenter } from "@/lib/optical-center"

/** Tinted initials — mirrors the Figma Avatar "Style=<hue>_primary" variants
 *  (tint/<hue> background + tint-text/<hue> text, both mode-aware tokens). */
type AvatarColor =
  | "indigo"
  | "blue"
  | "purple"
  | "pink"
  | "red"
  | "orange"
  | "yellow"
  | "green"
  | "alternative"
  | "grey"

type AvatarBadgeStatus = "available" | "busy" | "away" | "dnd" | "offline" | "unknown"

const AVATAR_COLOR_CLASSES: Record<AvatarColor, string> = {
  indigo: "bg-tint-indigo text-tint-text-indigo",
  blue: "bg-tint-blue text-tint-text-blue",
  purple: "bg-tint-purple text-tint-text-purple",
  pink: "bg-tint-pink text-tint-text-pink",
  red: "bg-tint-red text-tint-text-red",
  orange: "bg-tint-orange text-tint-text-orange",
  yellow: "bg-tint-yellow text-tint-text-yellow",
  green: "bg-tint-green text-tint-text-green",
  alternative: "bg-tint-alternative text-tint-text-alternative",
  grey: "bg-muted text-text-secondary",
}

// Owner rule (Oct 31 2026): the indicator sits top right with its centre on
// the corner of the shape. Circle of size s: centre at (0.854 s, 0.146 s).
// Rounded square of radius r: centre at (s - 0.293 r, 0.293 r). --badge-d is the dot size.
const BADGE_POSITION = "absolute top-[calc(14.645%-var(--badge-d)/2)] right-[calc(14.645%-var(--badge-d)/2)] z-10 inline-flex size-(--badge-d) items-center justify-center rounded-full bg-primary text-primary-foreground bg-blend-color ring-[1.5px] ring-(--surface) select-none [--badge-d:--spacing(2)] group-data-[shape=square]/avatar:top-[calc(var(--radius-md)*0.293-var(--badge-d)/2)] group-data-[shape=square]/avatar:right-[calc(var(--radius-md)*0.293-var(--badge-d)/2)]"

const STATUS_SHAPES: Record<AvatarBadgeStatus, React.ReactNode> = {
  available: <span aria-hidden className="size-full rounded-full bg-success" />,
  busy: (
    <span aria-hidden className="h-[20%] w-[60%] rounded-full bg-primary-foreground" />
  ),
  dnd: (
    <span aria-hidden className="h-[15%] w-[50%] rounded-full bg-error" />
  ),
  away: (
    <span aria-hidden className="flex size-[80%] items-center justify-center">
      <Moon className="size-full fill-current" strokeWidth={0} />
    </span>
  ),
  offline: null,
  unknown: null,
}

const STATUS_LABELS: Record<AvatarBadgeStatus, string> = {
  available: "Available",
  busy: "Busy",
  away: "Away",
  dnd: "Do not disturb",
  offline: "Offline",
  unknown: "Status unknown",
}

function Avatar({
  className,
  size = "default",
  shape = "circle",
  variant = "plain",
  color,
  interactive,
  selected,
  disabled,
  render,
  children,
  ...props
}: AvatarPrimitive.Root.Props & {
  /** Figma Avatar sizes: sm = 24px (2xs), xs = 28px, default = 36px (small), lg = 40px (medium), xl = 44px (large) */
  size?: "sm" | "xs" | "default" | "lg" | "xl"
  shape?: "circle" | "square"
  variant?: "plain" | "primary"
  /** Soft tint for initials avatars; ignored when an image renders. */
  color?: AvatarColor
  interactive?: boolean
  selected?: boolean
  disabled?: boolean
}) {
  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      data-size={size}
      data-shape={shape}
      data-variant={variant}
      data-color={color}
      data-interactive={interactive ? "" : undefined}
      data-selected={selected ? "" : undefined}
      data-disabled={disabled ? "" : undefined}
      {...(interactive && disabled ? { disabled: true } : {})}
      aria-pressed={interactive ? selected : undefined}
      render={interactive ? render ?? <button type="button" /> : render}
      className={cn(
        "group/avatar relative flex size-9 shrink-0 select-none after:absolute after:inset-0 after:border after:border-border-control after:mix-blend-darken dark:after:mix-blend-lighten",
        "data-[shape=circle]:rounded-full data-[shape=circle]:after:rounded-full",
        "data-[shape=square]:rounded-md data-[shape=square]:after:rounded-md",
        "data-[size=sm]:size-6 data-[size=xs]:size-7 data-[size=lg]:size-10 data-[size=xl]:size-11",
        // Figma keeps the glyph at 16 px and only shrinks it on the two small sizes.
        "[&_svg]:size-4 data-[size=sm]:[&_svg]:size-3 data-[size=xs]:[&_svg]:size-3.5",
        "data-[variant=primary]:bg-primary data-[variant=primary]:text-primary-foreground data-[variant=primary]:after:border-transparent",
        color && AVATAR_COLOR_CLASSES[color],
        color && "after:border-transparent",
        interactive && "cursor-pointer focus-ring data-[interactive]:focus-visible:after:border-primary data-[interactive]:focus-visible:after:mix-blend-normal data-[interactive]:hover:ring-3 data-[interactive]:hover:ring-bg-page data-[interactive]:active:ring-3 data-[interactive]:active:ring-bg-subtle data-[interactive]:data-[disabled]:opacity-40 data-[interactive]:data-[disabled]:pointer-events-none data-[interactive]:data-[selected]:ring-3 data-[interactive]:data-[selected]:ring-bg-subtle",
        className
      )}
      {...props}
    >
      {children}
      {selected && (
        <span
          data-slot="avatar-check"
          aria-hidden
          className={cn(
            BADGE_POSITION,
            "[--badge-d:--spacing(4)]",
            "group-data-[size=sm]/avatar:[--badge-d:--spacing(3)] group-data-[size=sm]/avatar:[&>svg]:size-2",
            "group-data-[size=xs]/avatar:[--badge-d:--spacing(3.5)] group-data-[size=xs]/avatar:[&>svg]:size-2.5",
            "group-data-[size=default]/avatar:[&>svg]:size-3",
            "group-data-[size=lg]/avatar:[&>svg]:size-3",
            "group-data-[size=xl]/avatar:[&>svg]:size-3"
          )}
        >
          <Check className="size-3" strokeWidth={3} />
        </span>
      )}
    </AvatarPrimitive.Root>
  )
}

function AvatarImage({ className, ...props }: AvatarPrimitive.Image.Props) {
  return (
    <AvatarPrimitive.Image
      data-slot="avatar-image"
      className={cn(
        "aspect-square size-full object-cover group-data-[shape=circle]/avatar:rounded-full group-data-[shape=square]/avatar:rounded-md",
        className
      )}
      {...props}
    />
  )
}

function AvatarFallback({
  className,
  children,
  ...props
}: AvatarPrimitive.Fallback.Props) {
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      className={cn(
        cn(
          "flex size-full items-center justify-center bg-muted text-foreground group-data-[shape=circle]/avatar:rounded-full group-data-[shape=square]/avatar:rounded-md",
          // Initials follow the Figma type ramp: 11 / 12 / 13 / 14 / 15 px,
          // semibold everywhere except the 28 px size, which is medium.
          "text-[13px] font-semibold",
          "group-data-[size=sm]/avatar:text-[11px]",
          "group-data-[size=xs]/avatar:text-[12px] group-data-[size=xs]/avatar:font-medium",
          "group-data-[size=lg]/avatar:text-[14px] group-data-[size=xl]/avatar:text-[15px]",
          "group-data-[variant=primary]/avatar:bg-transparent group-data-[variant=primary]/avatar:text-inherit",
          "group-data-[color]/avatar:bg-transparent group-data-[color]/avatar:text-inherit"
        ),
        className
      )}
      {...props}
    >
      {/* Initials sit on the cap-height centre of the circle, not on the line-box centre. */}
      {opticalCenter(children)}
    </AvatarPrimitive.Fallback>
  )
}

function AvatarBadge({
  className,
  status,
  ...props
}: React.ComponentProps<"span"> & {
  status?: AvatarBadgeStatus
}) {
  if (status) {
    const { children: _children, ...rest } = props
    return (
      <span
        data-slot="avatar-badge"
        data-status={status}
        role="img"
        aria-label={props["aria-label"] ?? STATUS_LABELS[status]}
        className={cn(
          BADGE_POSITION,
          "group-data-[size=sm]/avatar:[--badge-d:--spacing(2)]",
          "group-data-[size=xs]/avatar:[--badge-d:--spacing(2)]",
          "group-data-[size=lg]/avatar:[--badge-d:--spacing(2.5)]",
          "group-data-[size=xl]/avatar:[--badge-d:--spacing(3)]",
          "data-[status]:bg-transparent",
          "data-[status=available]:bg-success",
          "data-[status=busy]:bg-error",
          "data-[status=dnd]:bg-(--surface) data-[status=dnd]:border-[1.5px] data-[status=dnd]:border-error",
          "data-[status=away]:bg-(--surface) data-[status=away]:text-brand-quaternary",
          "data-[status=offline]:bg-(--surface) data-[status=offline]:border-[1.5px] data-[status=offline]:border-text-tertiary",
          "data-[status=unknown]:bg-(--surface) data-[status=unknown]:border-[1.5px] data-[status=unknown]:border-dashed data-[status=unknown]:border-text-tertiary",
          className
        )}
        {...rest}
      >
        {STATUS_SHAPES[status]}
      </span>
    )
  }

  return (
    <span
      data-slot="avatar-badge"
      className={cn(
        BADGE_POSITION,
        "group-data-[size=sm]/avatar:[&>svg]:hidden",
        "group-data-[size=xs]/avatar:[&>svg]:hidden",
        "group-data-[size=default]/avatar:[&>svg]:size-2",
        "group-data-[size=lg]/avatar:[--badge-d:--spacing(2.5)] group-data-[size=lg]/avatar:[&>svg]:size-2",
        "group-data-[size=xl]/avatar:[--badge-d:--spacing(3)] group-data-[size=xl]/avatar:[&>svg]:size-2",
        className
      )}
      {...props}
    />
  )
}

function AvatarGroup({ className, children, layout = "overlap", ...props }: React.ComponentProps<"div"> & {
  layout?: "overlap" | "spaced"
}) {
  const rootRef = React.useRef<HTMLDivElement>(null)

  // Distance-falloff hover lift: hovering one avatar lifts it and gently
  // lifts its neighbors, then everything snaps back with an overshoot spring
  // on mouseleave. The timing-function is set inline right before the
  // --avatar-shift/--avatar-scale writes so hover-in gets a clean ease and
  // the return gets the bouncy one, without a second class for "leaving".
  function setShifts(activeIndex: number | null, phase: "in" | "out") {
    const items = rootRef.current?.querySelectorAll<HTMLElement>("[data-avatar-hover-item]")
    if (!items) return
    const timing = phase === "out" ? "var(--ease-overshoot)" : "cubic-bezier(0.22, 1, 0.36, 1)"
    items.forEach((el, index) => {
      el.style.transitionTimingFunction = timing
      if (activeIndex == null) {
        el.style.setProperty("--avatar-shift", "0px")
        el.style.setProperty("--avatar-scale-active", "1")
        return
      }
      const distance = Math.abs(index - activeIndex)
      el.style.setProperty("--avatar-shift", `${(-4 * 0.45 ** distance).toFixed(3)}px`)
      el.style.setProperty("--avatar-scale-active", index === activeIndex ? "1.05" : "1")
    })
  }

  return (
    <div
      ref={rootRef}
      data-slot="avatar-group"
      data-layout={layout}
      onMouseLeave={() => setShifts(null, "out")}
      className={cn(
        "group/avatar-group flex",
